# login_window.py
import sys
import os
from PyQt5.QtWidgets import (QApplication, QMainWindow, QWidget, QVBoxLayout, QHBoxLayout, 
                             QPushButton, QLabel, QLineEdit, QMessageBox, QFrame)
from PyQt5.QtCore import Qt
from PyQt5.QtGui import QFont, QPixmap, QPalette, QBrush
import tempfile
import base64

class LoginWindow(QMainWindow):
    def __init__(self):
        super().__init__()
        self.temp_image_path = None
        self.init_ui()
        
    def init_ui(self):
        self.setWindowTitle('生命线工程设备测试数据分析软件 - 登录')
        self.setGeometry(300, 300, 1200, 800)
        self.setFixedSize(1200, 800)
        
        # 创建中央窗口部件
        central_widget = QWidget()
        self.setCentralWidget(central_widget)
        
        # 主布局 - 水平布局，左右分栏 (左侧2/3, 右侧1/3)
        main_layout = QHBoxLayout(central_widget)
        main_layout.setContentsMargins(0, 0, 0, 0)
        
        # 左侧 - 背景图片区域 (占2/3宽度)
        left_frame = QFrame()
        left_frame.setFixedWidth(800)  # 1200 * 2/3
        left_frame.setStyleSheet("background-color: #f0f0f0;")  # 默认背景色
        
        # 背景图片标签
        self.bg_label = QLabel()
        self.bg_label.setAlignment(Qt.AlignCenter)
        
        # 尝试加载背景图片
        if self.load_background_image():
            # 创建一个临时图片文件
            image_data = self.get_background_image_data()
            self.temp_image_path = os.path.join(tempfile.gettempdir(), 'bg_login.png')
            
            with open(self.temp_image_path, 'wb') as f:
                f.write(image_data)
            
            # 设置背景图片
            pixmap = QPixmap(self.temp_image_path)
            if not pixmap.isNull():
                scaled_pixmap = pixmap.scaled(800, 800, Qt.KeepAspectRatioByExpanding, Qt.SmoothTransformation)
                self.bg_label.setPixmap(scaled_pixmap)
                left_frame.setStyleSheet("")  # 清除默认背景色
        
        left_layout = QVBoxLayout(left_frame)
        left_layout.addWidget(self.bg_label)
        left_layout.setAlignment(Qt.AlignCenter)
        
        # 右侧 - 登录区域 (占1/3宽度)
        right_frame = QFrame()
        right_frame.setFixedWidth(400)  # 1200 * 1/3
        right_frame.setStyleSheet("background-color: white;")
        
        right_layout = QVBoxLayout(right_frame)
        
        # 标题区域 - 软件名和版本号
        title_frame = QFrame()
        title_frame.setFixedHeight(120)
        title_layout = QVBoxLayout(title_frame)
        title_layout.setAlignment(Qt.AlignCenter)
        
        title_label = QLabel('生命线工程设备测试数据分析软件')
        title_label.setAlignment(Qt.AlignCenter)
        title_label.setFont(QFont('SimSun', 16, QFont.Bold))
        title_label.setStyleSheet("color: #2c3e50; margin-top: 20px;")
        
        version_label = QLabel('V1.0')
        version_label.setAlignment(Qt.AlignCenter)
        version_label.setFont(QFont('SimSun', 14))
        version_label.setStyleSheet("color: #7f8c8d; margin-top: 5px;")
        
        title_layout.addWidget(title_label)
        title_layout.addWidget(version_label)
        
        # 登录框容器 - 位于中间
        login_container = QFrame()
        login_container.setFrameStyle(QFrame.StyledPanel)
        login_container.setStyleSheet("""
            QFrame {
                background-color: #f8f9fa;
                border: 2px solid #e9ecef;
                border-radius: 15px;
                padding: 25px;
            }
        """)
        login_layout = QVBoxLayout(login_container)
        login_layout.setAlignment(Qt.AlignCenter)
        
        # 账号输入
        self.username_label = QLabel('账号:')
        self.username_label.setFont(QFont('SimSun', 11))
        self.username_label.setStyleSheet("color: #2c3e50; margin-bottom: 5px;")
        self.username_input = QLineEdit()
        self.username_input.setPlaceholderText('请输入账号')
        self.username_input.setFont(QFont('SimSun', 11))
        self.username_input.setFixedWidth(200)
        self.username_input.setStyleSheet("""
            QLineEdit {
                padding: 8px;
                border: 2px solid #bdc3c7;
                border-radius: 6px;
                font-size: 11px;
            }
            QLineEdit:focus {
                border-color: #3498db;
            }
        """)
        
        # 密码输入
        self.password_label = QLabel('密码:')
        self.password_label.setFont(QFont('SimSun', 11))
        self.password_label.setStyleSheet("color: #2c3e50; margin-top: 10px; margin-bottom: 5px;")
        self.password_input = QLineEdit()
        self.password_input.setPlaceholderText('请输入密码')
        self.password_input.setFont(QFont('SimSun', 11))
        self.password_input.setEchoMode(QLineEdit.Password)
        self.password_input.setFixedWidth(200)
        self.password_input.setStyleSheet("""
            QLineEdit {
                padding: 8px;
                border: 2px solid #bdc3c7;
                border-radius: 6px;
                font-size: 11px;
            }
            QLineEdit:focus {
                border-color: #3498db;
            }
        """)
        
        # 登录按钮
        self.login_button = QPushButton('登录')
        self.login_button.setFont(QFont('SimSun', 11))
        self.login_button.setFixedWidth(200)
        self.login_button.setFixedHeight(35)
        self.login_button.setStyleSheet("""
            QPushButton {
                background-color: #3498db;
                color: white;
                border: none;
                border-radius: 6px;
                font-size: 12px;
                font-weight: bold;
            }
            QPushButton:hover {
                background-color: #2980b9;
            }
            QPushButton:pressed {
                background-color: #21618c;
            }
        """)
        self.login_button.clicked.connect(self.login)
        
        login_layout.addWidget(self.username_label)
        login_layout.addWidget(self.username_input)
        login_layout.addWidget(self.password_label)
        login_layout.addWidget(self.password_input)
        login_layout.addWidget(self.login_button)
        
        # 备注信息区域 - 版权和联系信息
        info_frame = QFrame()
        info_frame.setFixedHeight(180)
        info_layout = QVBoxLayout(info_frame)
        info_layout.setAlignment(Qt.AlignCenter)
        
        # 版权信息
        copyright_label = QLabel('© 2025 广东省建筑科学研究院集团股份有限公司\n路桥研究所&生命线工程技术中心')
        copyright_label.setAlignment(Qt.AlignCenter)
        copyright_label.setFont(QFont('SimSun', 9))
        copyright_label.setStyleSheet("color: #7f8c8d; margin-top: 10px;")
        
        # 联系邮箱
        contact_label = QLabel('账号密码获取联系邮箱: xiaotg@my.swjtu.edu.cn')
        contact_label.setAlignment(Qt.AlignCenter)
        contact_label.setFont(QFont('SimSun', 9))
        contact_label.setStyleSheet("color: #95a5a6; margin-top: 10px;")
        
        info_layout.addWidget(copyright_label)
        info_layout.addWidget(contact_label)
        info_layout.addStretch()
        
        # 将各部分添加到右侧布局
        right_layout.addWidget(title_frame)
        right_layout.addWidget(login_container)
        right_layout.addWidget(info_frame)
        right_layout.addStretch()  # 添加弹性空间使登录框居中
        
        # 添加左右两部分到主布局
        main_layout.addWidget(left_frame)
        main_layout.addWidget(right_frame)
        
    def get_background_image_data(self):
        """获取背景图片的字节数据（这里用一个简单的示例图片，实际使用时替换为您的图片）"""
                                                        # 这是一个非常简单的示例图片的base64编码
        # 您需要将实际的背景图片转换为base64编码
        sample_image_base64 = ""
        
        # 如果您有实际的背景图片文件，可以用以下代码转换：
        # with open('data/guipic.png', 'rb') as f:
        #     image_data = f.read()
        #     sample_image_base64 = base64.b64encode(image_data).decode('utf-8')
        
        return base64.b64decode(sample_image_base64)
    
    def load_background_image(self):
        """尝试加载背景图片"""
        try:
            # 首先尝试从data目录加载
            bg_path = os.path.join(os.path.dirname(__file__), 'data', 'guipic.png')
            if os.path.exists(bg_path):
                pixmap = QPixmap(bg_path)
                if not pixmap.isNull():
                    return True
            
            # 如果文件不存在，尝试从嵌入数据加载
            try:
                image_data = self.get_background_image_data()
                # 创建临时文件
                self.temp_image_path = os.path.join(tempfile.gettempdir(), 'bg_login.png')
                with open(self.temp_image_path, 'wb') as f:
                    f.write(image_data)
                return True
            except:
                return False
                
        except:
            return False
    
    def closeEvent(self, event):
        """窗口关闭时清理临时文件"""
        if self.temp_image_path and os.path.exists(self.temp_image_path):
            try:
                os.remove(self.temp_image_path)
            except:
                pass  # 忽略删除失败
        event.accept()
    
    def login(self):
        username = self.username_input.text()
        password = self.password_input.text()
        
        if username == 'admin' and password == 'gdjk123':
            from main import LifeLineAnalysisSoftware
            self.main_window = LifeLineAnalysisSoftware()
            self.main_window.show()
            self.close()
        else:
            QMessageBox.warning(self, '登录失败', '账号或密码错误，请重试！')
            self.username_input.clear()
            self.password_input.clear()

def main():
    app = QApplication(sys.argv)
    app.setStyle('Fusion')  # 使用现代化样式
    login_window = LoginWindow()
    login_window.show()
    sys.exit(app.exec_())

if __name__ == '__main__':
    main()